contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address impl, address settings, bytes calldata params, address ownedBy) public {
        require(impl != address(0) && settings != address(0));
        c.initialize();
        c.updateRoundImplementation(payable(impl));
        c.updateAlloSettings(settings);
        address clone = c.create(params, ownedBy);
        assert(
            clone != address(0) &&
            clone != impl &&
            clone.code.length > 0 &&
            c.roundImplementation() == impl &&
            c.alloSettings() == settings
        );
    }
}

