contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newAlloSettings) public payable {
        require(newAlloSettings != address(0));
        c.initialize();
        bool zeroImplReverted;
        // top-level statement pattern: use try outside? must be top-level; use separate call via try is not allowed nested
        // perform the zero-implementation update attempt
        // (try/catch wrapping a state-changing call is permitted as its own statement)
        try c.updateRoundImplementation(payable(0)) { zeroImplReverted = false; } catch { zeroImplReverted = true; }
        address before = c.alloSettings();
        c.updateAlloSettings(newAlloSettings);
        assert(zeroImplReverted && before == address(0) && c.alloSettings() == newAlloSettings);
    }
    receive() external payable {}
}
